dashboard.definition:
{
  "title": "ACME Showcase - All 16 Visualizations",
  "description": "One panel per ACME custom viz, populated with deterministic makeresults data.",
  "dataSources": {
    "ds_tile": {
      "type": "ds.search",
      "name": "Tile - Notable count + delta + spark",
      "options": {
        "query": "| makeresults | eval value=247, delta=-12, spark=\"120,140,160,150,170,190,180,200,210,200,220,247\""
      }
    },
    "ds_spark": {
      "type": "ds.search",
      "name": "Sparkline - 30 minute count",
      "options": {
        "query": "| makeresults count=30 | streamstats count as i | eval count=round(50+25*sin(i/4.0)+10*cos(i/1.7),0) | timechart span=1m sum(count) as count"
      }
    },
    "ds_area": {
      "type": "ds.search",
      "name": "Area chart - 24h threat events",
      "options": {
        "query": "| makeresults count=24 | streamstats count as h | eval _time=relative_time(now(), \"-\".(24-h).\"h\"), notable=round(40+20*sin(h/3.0)+(h*7)%10,0), blocked=round(80+30*cos(h/4.0)+(h*11)%15,0), authfail=round(30+15*sin(h/5.0)+(h*5)%8,0) | timechart span=1h max(notable) as notable max(blocked) as blocked max(authfail) as authfail"
      }
    },
    "ds_column": {
      "type": "ds.search",
      "name": "Column chart - hourly counts",
      "options": {
        "query": "| makeresults count=12 | streamstats count as h | eval _time=relative_time(now(), \"-\".(12-h).\"h\"), count=round(120+80*sin(h/4.0)+(h*13)%20,0) | timechart span=1h max(count) as count"
      }
    },
    "ds_hbar": {
      "type": "ds.search",
      "name": "H-bar list - top alert sources",
      "options": {
        "query": "| makeresults | eval rows=\"firewall:482,proxy:317,edr:268,authentication:214,dns:189,vpn:142,wafs:96\" | makemv delim=\",\" rows | mvexpand rows | rex field=rows \"(?<label>[^:]+):(?<value>[0-9]+)\" | table label, value"
      }
    },
    "ds_heatmap": {
      "type": "ds.search",
      "name": "Heatmap - MITRE tactic density",
      "options": {
        "query": "| makeresults | eval r=\"Initial Access:0,2,1,3,0,5,2|Execution:1,4,2,6,3,0,4|Persistence:0,1,0,2,1,0,3|Privilege Escalation:2,3,1,0,4,2,5|Defense Evasion:3,5,4,7,2,1,6|Credential Access:1,2,0,1,3,0,2|Discovery:4,3,5,2,1,3,4|Lateral Movement:0,1,2,0,3,1,2|Collection:1,0,1,2,3,2,1|Exfiltration:2,3,4,1,0,2,5|Impact:0,2,3,1,2,4,3\" | makemv delim=\"|\" r | mvexpand r | rex field=r \"(?<row>[^:]+):(?<vals>.*)\" | table row, vals"
      }
    },
    "ds_ring": {
      "type": "ds.search",
      "name": "Ring gauge - risk score",
      "options": { "query": "| makeresults | eval value=62" }
    },
    "ds_donut": {
      "type": "ds.search",
      "name": "Donut - revenue by region",
      "options": {
        "query": "| makeresults | eval rows=\"Americas:4250,EMEA:3120,APAC:2280,Other:1300\" | makemv delim=\",\" rows | mvexpand rows | rex field=rows \"(?<label>[^:]+):(?<value>[0-9.]+)\" | table label, value"
      }
    },
    "ds_funnel": {
      "type": "ds.search",
      "name": "Funnel - signup conversion",
      "options": {
        "query": "| makeresults | eval rows=\"Visitors:48210,Signups started:21640,Email verified:18430,Profile completed:14820,Subscribed:9380,Active 30d:6210\" | makemv delim=\",\" rows | mvexpand rows | rex field=rows \"(?<label>[^:]+):(?<value>[0-9]+)\" | table label, value"
      }
    },
    "ds_chip": {
      "type": "ds.search",
      "name": "Status chip - notables count",
      "options": { "query": "| makeresults | eval value=1247" }
    },
    "ds_table": {
      "type": "ds.search",
      "name": "Data table - recent notable events",
      "options": {
        "query": "| makeresults | eval rows=\"high;Brute force on web-prod-03;auth_combined;2m ago|crit;Suspicious data egress;netflow;5m ago|med;DNS tunnelling;dns;14m ago|low;Anomalous login from new geo;okta;22m ago|med;Malware artifact in upload;edr;38m ago|high;Privilege escalation attempt;audit_linux;44m ago|low;Outbound to known C2;firewall;1h ago\" | makemv delim=\"|\" rows | mvexpand rows | rex field=rows \"(?<severity>[^;]+);(?<event>[^;]+);(?<source>[^;]+);(?<time>[^;]+)\" | table severity, event, source, time"
      }
    },
    "ds_pop": {
      "type": "ds.search",
      "name": "PoP grid - 16 sites",
      "options": {
        "query": "| makeresults | eval rows=\"IAD:Ashburn:ok:64|ORD:Chicago:ok:48|DFW:Dallas:warn:78|SJC:San Jose:ok:52|LHR:London:ok:61|FRA:Frankfurt:warn:82|AMS:Amsterdam:ok:44|CDG:Paris:ok:55|NRT:Tokyo:ok:39|SIN:Singapore:warn:71|SYD:Sydney:ok:42|HKG:Hong Kong:danger:91|GRU:Sao Paulo:ok:35|YUL:Montreal:ok:48|JNB:Johannesburg:ok:29|DXB:Dubai:warn:73\" | makemv delim=\"|\" rows | mvexpand rows | rex field=rows \"(?<code>[^:]+):(?<name>[^:]+):(?<status>[^:]+):(?<util>[0-9]+)\" | table code, name, status, util"
      }
    },
    "ds_chrome": {
      "type": "ds.search",
      "name": "Chrome trigger - single row",
      "options": { "query": "| makeresults | eval x=1" }
    }
  },
  "visualizations": {
    "viz_app_bar": {
      "type": "acme_splunk_viz.app_bar",
      "dataSources": { "primary": "ds_chrome" },
      "options": {
        "theme": "dark",
        "appName": "Enterprise Security",
        "navItems": "Apps,Search & Reporting,Dashboards,Alerts,Datasets",
        "activeNavIndex": "2",
        "userInitials": "JH"
      }
    },
    "viz_filter_strip": {
      "type": "acme_splunk_viz.filter_strip",
      "dataSources": { "primary": "ds_chrome" },
      "options": {
        "theme": "dark",
        "filters": "Time range:Last 24 hours|Environment:Production|Index:notable|Severity:All",
        "ctaLabel": "Run search"
      }
    },
    "viz_tile": {
      "type": "acme_splunk_viz.single_value_tile",
      "dataSources": { "primary": "ds_tile" },
      "options": {
        "theme": "dark",
        "label": "Notable events (24h)",
        "subLabel": "vs prev 24h",
        "valueField": "value",
        "deltaField": "delta",
        "sparkField": "spark",
        "deltaSemantics": "down-good",
        "accent": "#ff6600",
        "showSparkline": "true"
      }
    },
    "viz_chip": {
      "type": "acme_splunk_viz.status_chip",
      "dataSources": { "primary": "ds_chip" },
      "options": {
        "theme": "dark",
        "variant": "header",
        "label": "Notables",
        "valueField": "value",
        "color": "#ff6600"
      }
    },
    "viz_wordmark": {
      "type": "acme_splunk_viz.wordmark",
      "dataSources": { "primary": "ds_chrome" },
      "options": {
        "theme": "dark",
        "subMark": "Enterprise Security",
        "size": "17"
      }
    },
    "viz_area": {
      "type": "acme_splunk_viz.area_chart",
      "dataSources": { "primary": "ds_area" },
      "options": {
        "theme": "dark",
        "colors": "#ff6600,#2bbfb8,#7eb1ff",
        "gridY": "4",
        "markerIdx": "-1",
        "markerSeries": "0"
      }
    },
    "viz_donut": {
      "type": "acme_splunk_viz.donut",
      "dataSources": { "primary": "ds_donut" },
      "options": {
        "theme": "dark",
        "colors": "#2bbfb8,#5ce1e6,#7eb1ff,#a78bfa",
        "centerLabel": "$10.95M",
        "centerSubLabel": "total Q2",
        "legendPosition": "right"
      }
    },
    "viz_column": {
      "type": "acme_splunk_viz.column_chart",
      "dataSources": { "primary": "ds_column" },
      "options": {
        "theme": "dark",
        "color": "#2bbfb8",
        "highlightColor": "#ff6600",
        "highlightIndex": "7",
        "gridY": "4",
        "maxBarWidth": "20"
      }
    },
    "viz_ring": {
      "type": "acme_splunk_viz.ring_gauge",
      "dataSources": { "primary": "ds_ring" },
      "options": {
        "theme": "dark",
        "field": "value",
        "max": "100",
        "thick": "11",
        "label": "Risk Score",
        "sub": "current",
        "color": "#ff6600",
        "half": "false",
        "showLegend": "true"
      }
    },
    "viz_sparkline": {
      "type": "acme_splunk_viz.sparkline",
      "dataSources": { "primary": "ds_spark" },
      "options": {
        "theme": "dark",
        "field": "count",
        "color": "#2bbfb8",
        "fill": "true",
        "strokeWidth": "1.5"
      }
    },
    "viz_hbar": {
      "type": "acme_splunk_viz.h_bar_list",
      "dataSources": { "primary": "ds_hbar" },
      "options": {
        "theme": "dark",
        "colors": "#2bbfb8,#5ce1e6,#7eb1ff",
        "spotlightIndex": "0",
        "spotlightColor": "#ff6600",
        "maxRows": "7"
      }
    },
    "viz_funnel": {
      "type": "acme_splunk_viz.funnel",
      "dataSources": { "primary": "ds_funnel" },
      "options": {
        "theme": "dark",
        "color": "#2bbfb8",
        "dropoffWarnThreshold": "30"
      }
    },
    "viz_heatmap": {
      "type": "acme_splunk_viz.heatmap",
      "dataSources": { "primary": "ds_heatmap" },
      "options": {
        "theme": "dark",
        "flavor": "mitre",
        "showCellValues": "true",
        "cellHigh": "#ff6600",
        "cellExtreme": "#d41f1f",
        "legendLow": "Less",
        "legendHigh": "More"
      }
    },
    "viz_table": {
      "type": "acme_splunk_viz.data_table",
      "dataSources": { "primary": "ds_table" },
      "options": {
        "theme": "dark",
        "columns": "severity:Severity:badge:90,event:Event:text:flex,source:Source:mono:160,time:Time:text:120:right",
        "maxRows": "50",
        "errorThreshold": "1.0"
      }
    },
    "viz_pop_grid": {
      "type": "acme_splunk_viz.pop_grid",
      "dataSources": { "primary": "ds_pop" },
      "options": {
        "theme": "dark",
        "columns": "4",
        "codeField": "code",
        "nameField": "name",
        "statusField": "status",
        "utilField": "util"
      }
    },
    "viz_dashboard_frame": {
      "type": "acme_splunk_viz.dashboard_frame",
      "dataSources": { "primary": "ds_chrome" },
      "options": {
        "theme": "dark",
        "appName": "Enterprise Security",
        "breadcrumb": "Apps - Enterprise Security - Dashboards",
        "title": "Security operations overview",
        "subtitle": "Real-time across all production indexes - auto-refresh 30s",
        "statusPills": "Notables:1247:#ff6600|Open:182:#cba700|Healthy::#118832",
        "footerLeft": "index=notable | stats count by source",
        "footerRight": "build 1.0.2",
        "showFilters": "true"
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time Range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "globalInputs": ["input_global_trp"],
    "structure": [
      { "item": "viz_app_bar",         "type": "block", "position": { "x": 0,    "y": 0,    "w": 1200, "h": 48 } },
      { "item": "viz_filter_strip",    "type": "block", "position": { "x": 0,    "y": 48,   "w": 1200, "h": 60 } },

      { "item": "viz_tile",            "type": "block", "position": { "x": 0,    "y": 108,  "w": 400,  "h": 140 } },
      { "item": "viz_chip",            "type": "block", "position": { "x": 400,  "y": 108,  "w": 400,  "h": 140 } },
      { "item": "viz_wordmark",        "type": "block", "position": { "x": 800,  "y": 108,  "w": 400,  "h": 140 } },

      { "item": "viz_area",            "type": "block", "position": { "x": 0,    "y": 248,  "w": 800,  "h": 320 } },
      { "item": "viz_donut",           "type": "block", "position": { "x": 800,  "y": 248,  "w": 400,  "h": 320 } },

      { "item": "viz_column",          "type": "block", "position": { "x": 0,    "y": 568,  "w": 600,  "h": 280 } },
      { "item": "viz_ring",            "type": "block", "position": { "x": 600,  "y": 568,  "w": 300,  "h": 280 } },
      { "item": "viz_sparkline",       "type": "block", "position": { "x": 900,  "y": 568,  "w": 300,  "h": 280 } },

      { "item": "viz_hbar",            "type": "block", "position": { "x": 0,    "y": 848,  "w": 400,  "h": 360 } },
      { "item": "viz_funnel",          "type": "block", "position": { "x": 400,  "y": 848,  "w": 400,  "h": 360 } },
      { "item": "viz_heatmap",         "type": "block", "position": { "x": 800,  "y": 848,  "w": 400,  "h": 360 } },

      { "item": "viz_table",           "type": "block", "position": { "x": 0,    "y": 1208, "w": 1200, "h": 360 } },

      { "item": "viz_pop_grid",        "type": "block", "position": { "x": 0,    "y": 1568, "w": 600,  "h": 400 } },
      { "item": "viz_dashboard_frame", "type": "block", "position": { "x": 600,  "y": 1568, "w": 600,  "h": 400 } }
    ]
  }
}
